 if(v==='would'&&['rather','prefer'].includes(n))add('would-rather','Предпочтение',i,Math.min(i+2,t.length-1),'Would rather + начальная форма: «предпочёл бы». После would prefer обычно используется to-инфинитив или существительное.','I’d rather stay. — Я предпочёл бы остаться.');
 if(v==='let'||v==="let's"||['make','made'].includes(v)&&['me','him','her','us','them'].includes(n))add('bare-inf','Let / make + объект + действие',i,Math.min(i+2,t.length-1),'После let и активного make объект часто сопровождается глаголом без to: let me go, made her feel. В пассиве make используется с to.','The hot day made her feel sleepy. — Из-за жары ей хотелось спать.','possible');
 if(['see','saw','hear','heard','watch','watched','feel','felt'].includes(v)&&['him','her','them','it','me','us'].includes(n))add('perception','Восприятие + объект + действие',i,Math.min(i+2,t.length-1),'После see / hear / watch возможны начальная форма без to (событие целиком) и -ing (наблюдаемый процесс).','I saw her run / running. — Я видел, как она побежала / бежала.','possible');
