 if(v==='too'&&n||v==='enough'&&p)add('too-enough','Too / enough',Math.max(0,i-1),Math.min(i+2,t.length-1),'Too + признак — «слишком». Признак + enough — «достаточно». Enough стоит перед существительным: enough time. Too также означает «тоже».','Too tired to work — слишком устал, чтобы работать.','possible');
 if(['in','on','at','to','from','by','with','of','for','about','under','over','between','among','through','during','into','onto','without','within','behind','beside','across'].includes(v)&&n&&!(v==='to'&&candidates(n).some(x=>knownVerbs.has(x))))add('prep-'+v,'Предлог: '+v,i,i+1,'Предлог связывает слова и обозначает место, время, направление, причину или другое отношение. Перевод зависит от сочетания целиком; после предлога используются объектные местоимения и герундий.','On the bank — на берегу; at five — в пять; without waiting — не дожидаясь.','found','Предлоги');
 if(/'s$/.test(v)&&!['it','he','she','there','that','what','who','here'].includes(v.slice(0,-2)))add('possessive-s','Притяжательная форма ’s',i,Math.min(i+1,t.length-1),'После имени или существительного ’s часто выражает принадлежность. После множественного числа на -s обычно ставят только апостроф. Но ’s также бывает сокращением is / has.','Alice’s book — книга Алисы; the students’ books — книги студентов.','possible');
 if(v==='so'&&n==='that'||v==='such'&&['a','an'].includes(n))add('result','So / such … that',i,Math.min(i+3,t.length-1),'So + признак или such + именная группа могут выражать степень с результатом: «настолько…, что…».','It was so dark that I couldn’t see.','possible');
 if(['nothing','something','anything','somebody','someone','anyone','nobody'].includes(v)&&n==='to')add('indef-inf','Неопределённое местоимение + инфинитив',i,Math.min(i+2,t.length-1),'После nothing / something / anything инфинитив уточняет возможное действие: нечего / что-нибудь / что-либо сделать.','Nothing to do — нечего делать. Something to read — что-нибудь почитать.');
 if(v==='not'&&n==='only')add('not-only','Not only … but also',i,Math.min(i+4,t.length-1),'Парное сочетание соединяет однородные части: «не только…, но и…». В начале предложения not only может вызывать обратный порядок слов.','Not only did she read, but she also wrote.','possible');
