export type WordMeaning={lemma:string;pos:string;label:string;translations:string[];tag:string};
/** Every sense in the full preloaded index, with no per-word request or truncation. */
export function allMeaningsReady(raw:string,context=raw,at=0):WordMeaning[]{
 if(!dictionaryData)return[];const roots=candidates(raw.toLowerCase().replace(/’/g,"'")),result:WordMeaning[]=[];const seen=new Set<string>();
 for(const lemma of roots)for(const entry of dictionaryData[lemma]||[])for(const sense of entry.s){const translations=Array.from(new Set(sense.t));const key=entry.p+'|'+translations.join('|');if(!translations.length||seen.has(key))continue;seen.add(key);result.push({lemma,pos:entry.p,label:posNames[entry.p]||entry.p||'значение',translations,tag:sense.d});}
 const preferred=lookupInstant(raw,context,at);if(preferred)result.sort((a,b)=>Number(b.translations.includes(preferred.translation))-Number(a.translations.includes(preferred.translation)));
 if(!result.length&&preferred&&preferred.translation!=='Слово не найдено')result.push({lemma:preferred.lemma||raw,pos:preferred.pos||'',label:posNames[preferred.pos||'']||'значение',translations:[preferred.translation,...preferred.alternatives||[]],tag:''});return result;
}
